package com.bank.lookup;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class LookupDemo {
    private static final Logger log = Logger.getLogger("Lookup");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(30L, "Rajesh"),
            new Employee(10L, "Priya"),
            new Employee(20L, "Amit")
        );
        LookupService service = new LookupService();
        Map<Long, String> lookup = service.orderedIdToName(staff);
        lookup.forEach((id, name) -> log.info(() -> id + " -> " + name));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    Employee(Long id, String name) { this.id = id; this.name = name; }
    Long getId() { return id; }
    String getName() { return name; }
}

// ─── Would be in service/LookupService.java ───
class LookupService {
    // LinkedHashMap::new supplier preserves the original (insertion) order.
    Map<Long, String> orderedIdToName(List<Employee> employees) {
        return employees.stream()
            .collect(toMap(
                Employee::getId,
                Employee::getName,
                (a, b) -> a,            // merge (ids expected unique; keep first on clash)
                LinkedHashMap::new));   // preserve insertion order
    }
}
